/* Golden test for the embedded C analytic IK port.
 *
 * The reference target is generated by ArmSim ForwardKinematics. The C solver must
 * recover the original joint angles for the same branch and arm angle.
 */
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <random>

#include "ik.h"
#include "kinematics.h"

extern "C" {
#include "../../../Real/DIYcontroller/LibSE/Algorithm/Kinematics/ik_analytic.h"
}

namespace {

constexpr int kSamples = 500;

const DhTable kDh = {{
    {0.0f, 0.4105f, -0.0897f, -72.5122038f},
    {90.0f, 0.0f, 0.0f, -90.0f},
    {90.0f, 0.0f, 0.188f, -90.0f},
    {90.0f, 0.0f, -0.0025f, 170.7537190f},
    {90.0f, 0.0f, 0.207f, 10.6949890f},
    {90.0f, 0.0f, 0.0f, -148.8585943f},
    {90.0f, 0.0f, 0.0f, 0.0f},
}};

const JointArray kMin = {-90.0f, -20.0f, -175.0f, -110.0f, -175.0f, -120.0f, -175.0f};
const JointArray kMax = {90.0f, 175.0f, 175.0f, 110.0f, 175.0f, 70.0f, 175.0f};

DhParam ToReference(const DH_Param_t &row)
{
    return {row.alpha_deg, row.a_m, row.d_m, row.theta_offset_deg};
}

DhTable MakeReferenceTable(const DH_Param_t source[IK_ANALYTIC_JOINTS])
{
    DhTable table{};

    for (int i = 0; i < kJointCount; ++i) {
        table[static_cast<size_t>(i)] = ToReference(source[i]);
    }
    return table;
}

float AngleDistance(float a, float b)
{
    return std::fabs(std::remainder(a - b, 360.0f));
}

void CopyTarget(const Mat4 &source, float target[4][4])
{
    for (int row = 0; row < 4; ++row) {
        for (int column = 0; column < 4; ++column) {
            target[row][column] = source(row, column);
        }
    }
}

}  // namespace

int main()
{
    DH_Param_t c_dh[IK_ANALYTIC_JOINTS] = {
        {0.0f, 0.4105f, -0.0897f, -72.5122038f},
        {90.0f, 0.0f, 0.0f, -90.0f},
        {90.0f, 0.0f, 0.188f, -90.0f},
        {90.0f, 0.0f, -0.0025f, 170.7537190f},
        {90.0f, 0.0f, 0.207f, 10.6949890f},
        {90.0f, 0.0f, 0.0f, -148.8585943f},
        {90.0f, 0.0f, 0.0f, 0.0f},
    };
    IkAnalyticSrsParam_t c_srs;
    const DhTable reference_dh = MakeReferenceTable(c_dh);
    SrsParam reference_srs;

    if (!IkAnalytic_MakeSrsParam(c_dh, &c_srs) ||
        !MakeSrsParam(reference_dh, reference_srs)) {
        std::fprintf(stderr, "S-R-S parameter extraction failed\n");
        return 1;
    }

    std::mt19937 generator(20261125U);
    int checked = 0;
    int skipped = 0;
    float worst_angle_error = 0.0f;
    float worst_roundtrip_error = 0.0f;
    float worst_psi_error = 0.0f;

    for (int sample = 0; sample < kSamples; ++sample) {
        JointArray q{};

        for (int i = 0; i < kJointCount; ++i) {
            q[static_cast<size_t>(i)] =
                std::uniform_real_distribution<float>(
                    kMin[static_cast<size_t>(i)],
                    kMax[static_cast<size_t>(i)])(generator);
        }

        const Mat4 target = ForwardKinematics(reference_dh, q);
        const ArmAngle arm_angle =
            ComputeArmAngle(reference_srs, ForwardKinematicsFrames(reference_dh, q));
        const Branch branch = ComputeBranch(reference_dh, q);
        if (!arm_angle.valid || !branch.valid) {
            ++skipped;
            continue;
        }

        float target_c[4][4];
        float q_c[IK_ANALYTIC_JOINTS];
        float psi_c = 0.0f;
        IkAnalyticBranch_t branch_c;
        IkAnalyticResult_t solved_c;

        CopyTarget(target, target_c);
        for (int i = 0; i < kJointCount; ++i) {
            q_c[i] = q[static_cast<size_t>(i)];
        }
        if (!IkAnalytic_ComputeArmAngle(c_dh, &c_srs, q_c, &psi_c) ||
            !IkAnalytic_ComputeBranch(c_dh, q_c, &branch_c)) {
            std::fprintf(stderr, "sample %d: C branch/psi failed\n", sample);
            return 2;
        }

        if (branch_c.shoulder != branch.shoulder ||
            branch_c.elbow != branch.elbow ||
            branch_c.wrist != branch.wrist) {
            std::fprintf(stderr, "sample %d: branch mismatch\n", sample);
            return 3;
        }

        worst_psi_error =
            std::max(worst_psi_error, AngleDistance(psi_c, arm_angle.psi_deg));
        IkAnalytic_Solve(&c_srs, target_c, &branch_c, psi_c, &solved_c);
        if (solved_c.status != IK_ANALYTIC_OK) {
            std::fprintf(stderr, "sample %d: solve status %d\n", sample,
                         static_cast<int>(solved_c.status));
            return 4;
        }

        const IkResult reference_solved =
            SolveIk(reference_srs, target, branch, psi_c);
        if (reference_solved.status != IkStatus::Ok) {
            std::fprintf(stderr, "sample %d: reference solve failed\n", sample);
            return 5;
        }
        for (int i = 0; i < kJointCount; ++i) {
            const float error =
                AngleDistance(solved_c.q_deg[i],
                              reference_solved.q_deg[static_cast<size_t>(i)]);
            const float roundtrip_error =
                AngleDistance(solved_c.q_deg[i], q[static_cast<size_t>(i)]);

            worst_angle_error = std::max(worst_angle_error, error);
            worst_roundtrip_error =
                std::max(worst_roundtrip_error, roundtrip_error);
            if (error > 1e-4f) {
                std::fprintf(stderr,
                             "sample %d joint %d C %.8f reference %.8f err %.8f\n",
                             sample, i, solved_c.q_deg[i],
                             reference_solved.q_deg[static_cast<size_t>(i)],
                             error);
                return 6;
            }
        }
        ++checked;
    }

    std::printf("analytic C golden: checked=%d skipped=%d\n", checked, skipped);
    std::printf("worst C/reference error=%.8f deg, worst roundtrip=%.6f deg, "
                "worst psi error=%.6f deg\n",
                worst_angle_error, worst_roundtrip_error, worst_psi_error);
    return checked > 0 ? 0 : 7;
}
